		},
		{
			name: "trailing slash is normalized", target: scanTarget{Kind: kindRepo, Name: secRepo + "/"},
			failures:  []jobs.Failure{secFailure(jobs.KindScan, secCtx, secRepo, t0)},
			wantState: indicator.Failed,
		},
