func hasAnyGlyph(line string) bool {
	for _, s := range indicator.States() {
		if g := indicator.Glyph(s, true); g != "" && strings.Contains(line, g) {
			return true
		}
	}
	return strings.Contains(line, indicator.Glyph(indicator.Running, false))
}

